<script setup>import{Head,router}from'@inertiajs/vue3';defineProps({quotation:Object,acceptUrl:String,rejectUrl:String});</script><template><Head :title="quotation.quotation_number"/><main class="min-h-screen bg-slate-100 p-4 sm:p-10"><div v-if="$page.props.flash.success" class="success-message mx-auto mb-4 max-w-4xl">{{ $page.props.flash.success }}</div><article class="mx-auto max-w-4xl rounded-2xl bg-white p-8 shadow print:shadow-none"><header class="flex justify-between"><div><h1 class="text-2xl font-bold text-[#0B3D6E]">KernelBridge Technologies LTD</h1><p>Bridging Ideas to Smart Digital Solutions</p></div><div class="text-right"><strong>QUOTATION</strong><p>{{ quotation.quotation_number }}</p></div></header><section class="my-8"><h2 class="text-xl font-bold">{{ quotation.customer.name }}</h2><p>{{ quotation.customer.billing_address }}</p><p>Valid until {{ quotation.expiry_date }}</p></section><table class="w-full"><thead><tr class="border-b"><th class="py-3 text-left">Description</th><th>Qty</th><th class="text-right">Total</th></tr></thead><tbody><tr v-for="i in quotation.items" :key="i.uuid" class="border-b"><td class="py-4">{{ i.product }} {{ i.plan }}<br/><small>{{ i.description }}</small></td><td class="text-center">{{ i.quantity }}</td><td class="text-right">{{ quotation.currency }} {{ i.total }}</td></tr></tbody></table><p class="mt-8 text-right text-2xl font-bold">Total: {{ quotation.currency }} {{ quotation.total }}</p><div class="mt-10 whitespace-pre-line text-sm">{{ quotation.terms }}</div><div v-if="quotation.status==='sent'" class="mt-8 flex justify-end gap-3 print:hidden"><button class="rounded-xl border border-red-200 px-6 py-3 font-bold text-red-700" @click="router.post(rejectUrl)">Reject</button><button class="form-button" @click="router.post(acceptUrl)">Accept quotation</button></div><p v-else class="mt-8 text-right font-bold uppercase">{{ quotation.status }}</p><button onclick="window.print()" class="mt-5 rounded-xl border px-5 py-2 print:hidden">Print / Save PDF</button></article></main></template>
